            | "hotel.perimeter.refresh"
            | "hotel.egress.check"
            | "agent.configure"
            | "skill.register"
            | "subagent.spawn"
            | "role.configure"
            | "role.list"
            | "role.set_home"
            | "transport.set_home"
            | "bash.exec"
            | "training.list"
            | "training.correct"
            | "training.export"
            | "training.status"
            | "asr.setup"
            | "asr.status"
            | "vision.setup"
            | "vision.status"
            | "cron.register"
            | "cron.list"
            | "cron.enable"
            | "cron.disable"
